//! Encoding helpers.
//!
//! Generated by gen-isa from the ISA spec.

#![allow(unused_parens, clippy::all)]

use crate::Instruction;
use crate::opcode::Opcode;
use sw_isa_core::EncodeError;

pub fn encode(insn: &Instruction, out: &mut [u8]) -> Result<usize, EncodeError> {
    match insn {
        Instruction::Short { op, tag, disp } => encode_short(*op, *tag, *disp, out),
        Instruction::Long {
            op,
            tag,
            indirect,
            address,
        } => encode_long(*op, *tag, *indirect, *address, out),
    }
}

fn encode_short(op: Opcode, tag: u8, disp: i8, out: &mut [u8]) -> Result<usize, EncodeError> {
    if out.len() < 2 {
        return Err(EncodeError::BufferTooSmall);
    }
    let mut word: u16 = 0;
    word |= ((op as u16) & 0x1F) << 11;
    word |= ((tag as u16) & 0x3) << 8;
    word |= ((disp as u8 as u16) & 0xFF);
    out[..2].copy_from_slice(&word.to_be_bytes());
    Ok(2)
}

fn encode_long(
    op: Opcode,
    tag: u8,
    indirect: bool,
    address: u16,
    out: &mut [u8],
) -> Result<usize, EncodeError> {
    if out.len() < 4 {
        return Err(EncodeError::BufferTooSmall);
    }
    let mut word: u32 = 0;
    word |= ((op as u32) & 0x1F) << 27;
    word |= (1u32) << 26;
    word |= ((tag as u32) & 0x3) << 24;
    word |= ((indirect as u32) & 0x1) << 23;
    word |= ((address as u32) & 0xFFFF);
    out[..4].copy_from_slice(&word.to_be_bytes());
    Ok(4)
}

