input.content:
//! Disassembler: bytes -> textual asm.
//!
//! The output is the round-trip-stable form: re-parsing it should
//! produce instructions whose encoded bytes equal the input. Names
//! are not recovered (we never had them in the byte stream); operands
//! are emitted as numeric literals.

use sw_ibm1130_isa::{Architecture, Ibm1130, Instruction, Opcode, decode};

use crate::AsmError;

/// Disassemble a byte stream into asm text. Each instruction
/// becomes one line. Errors mid-stream are reported with a virtual
/// "line" matching the instruction index (1-based).
pub fn disassemble(bytes: &[u8]) -> Result<String, AsmError> {
    let mut out = String::new();
    let mut offset = 0;
    let mut idx: u32 = 1;
    while offset < bytes.len() {
        let pc = <Ibm1130 as Architecture>::Address::from(sw_ibm1130_isa::Addr(offset as u32));
        let _ = pc; // suppress unused; decode does not consume pc here.
        let (insn, n) = decode::decode(&bytes[offset..]).map_err(|e| {
            AsmError::new(idx, 1, format!("decode failed at byte {offset}: {e:?}"))
        })?;
        out.push_str(&render_instruction(&insn));
        out.push('\n');
        offset += n;
        idx += 1;
    }
    Ok(out)
}

/// Render one decoded instruction into a single asm line.
pub fn render_instruction(insn: &Instruction) -> String {
    match insn {
        Instruction::Short { op, tag, disp } => {
            let mnem = op.mnemonic();
            if *tag == 0 {
                format!("        {} {}", mnem, disp)
            } else {
                format!("        {} {},{}", mnem, tag, disp)
            }
        }
        Instruction::Long {
            op,
            tag,
            indirect,
            address,
        } => {
            let mnem = op.mnemonic();
            let mut s = String::from("        ");
            s.push_str(mnem);
            s.push(' ');
            s.push('L');
            if *indirect {
                s.push_str(" I");
            }
            s.push(' ');
            if *tag != 0 {
                s.push_str(&tag.to_string());
                s.push(',');
            }
            s.push_str(&format!("0x{:04x}", address));
            s
        }
    }
}

// `Architecture::Address` doesn't have a public From<Addr>; this
// dummy keeps the `let _ = pc;` line above well-typed without
// touching `sw-ibm1130-isa`.
trait FromAddr: Sized {
    fn from(a: sw_ibm1130_isa::Addr) -> Self;
}
impl FromAddr for sw_ibm1130_isa::Addr {
    fn from(a: sw_ibm1130_isa::Addr) -> Self {
        a
    }
}
trait Architecture2 {
    type Address;
}
impl Architecture2 for Ibm1130 {
    type Address = sw_ibm1130_isa::Addr;
}

// Re-export so `disassemble` can read `Opcode::mnemonic`.
#[allow(unused_imports)]
use sw_ibm1130_isa::opcode::Opcode as _;

