#[test]
fn round_trip_short_and_long_mix() {
    let src = "\
        A 5\n\
        S -10\n\
        LD L 0x4000\n\
        STO L I 0x42\n\
        BSC 0x20\n\
        BSI L 0x1000\n\
        MDX 1, 4\n\
        WAIT\n\
        XIO L 0x200\n\
";
    let out = assemble_ok(src);
