}

#[test]
fn round_trip_all_24_mnemonics() {
    let src = r#"
        LD 5
        LDD 6
        STO 7
        STD 8
        LDX 9
        STX 10
        LDS 11
        STS 12
        A 5
        AD 6
        S 7
        SD 8
        M 9
        D 10
        AND 11
        OR 12
        EOR 13
        SLA 1
        SRA 2
        BSC 0x20
        BSI L 0x100
        MDX 5
