}

#[test]
fn round_trip_with_dc_and_org() {
    let src = "\
                ORG 4\n\
        FOO     DC 0x1234\n\
        BAR     DC 0xDEAD\n\
                A L FOO\n\
                S L BAR\n\
";
    let out = assemble_ok(src);
    // Reassemble the disassembly. The reassembled bytes won't equal
    // the original because ORG padding is present in the bytes; we
    // assert that (re-disasm -> reassemble) is at least a fixed
    // point: text -> bytes -> text round-trip.
    let text1 = disassemble(&out.bytes).unwrap();
    let again = assemble_ok(&text1);
    let text2 = disassemble(&again.bytes).unwrap();
    assert_eq!(text1, text2);
}

