    // ORG fills with zero words; we don't round-trip these (0x0000
    // is not a valid opcode) but we do verify the byte layout.
    let out = assemble_ok(
        "        ORG 4\n\
                A 5\n",
    );
    assert_eq!(out.bytes.len(), 4 * 2 + 2);
    assert_eq!(&out.bytes[..8], &[0, 0, 0, 0, 0, 0, 0, 0]);
}

