49	                Directive::Dc(op) => {
50	                    let v = resolve(op, symbols, line.line)?;
51	                    let word = (v as i32 as u32 as u16).to_be_bytes();
52	                    bytes.extend_from_slice(&word);
53	                    instructions.push(Instruction::Long {
54	                        op: Opcode::Wait,
55	                        tag: 0,
56	                        indirect: false,
57	                        address: v as u16,
58	                    });
59	                    lc += 1;
60	                }
61	                Directive::End => break,
62	            },
63	            LineBody::Instruction(insn) => {
64	                let opcode = mnemonic_to_opcode(&insn.mnemonic, line.line, insn.mnemonic_col)?;
65	                let force_short = is_short_only(&insn.mnemonic);
66	                let want_long =
67	                    (insn.long_flag || insn.indirect_flag || is_long_only(&insn.mnemonic))
68	                        && !force_short;
69	
70	                if force_short && (insn.long_flag || insn.indirect_flag) {
71	                    return Err(AsmError::new(
72	                        line.line,
73	                        insn.mnemonic_col,
74	                        format!("`{}` has no long form", insn.mnemonic),
75	                    ));
76	                }
77	
78	                let built = if want_long {
79	                    build_long(insn, opcode, symbols, line.line)?
80	                } else {
81	                    build_short(insn, opcode, symbols, line.line)?
82	                };
83	
84	                let mut buf = [0u8; 4];
85	                let n = encode::encode(&built, &mut buf).map_err(|e| {
86	                    AsmError::new(
87	                        line.line,
88	                        insn.mnemonic_col,
89	                        format!("encode failed: {e:?}"),
90	                    )
91	                })?;
92	                bytes.extend_from_slice(&buf[..n]);
93	                instructions.push(built);
94	                lc += instruction_size_words(insn);
95	            }
96	        }
97	    }
98	
99	    Ok(AsmOutput {
100	        bytes,
101	        symbols: symbols.clone(),
102	        instructions,
103	    })
104	}
