106	fn build_short(
107	    insn: &crate::parser::Instruction,
108	    op: Opcode,
109	    symbols: &SymbolTable,
110	    line: u32,
111	) -> Result<Instruction, AsmError> {
112	    let disp_value = match &insn.operand {
113	        Some(o) => resolve(o, symbols, line)?,
114	        None => 0,
115	    };
116	    if !(-128..=127).contains(&disp_value) {
117	        return Err(AsmError::new(
118	            line,
119	            insn.mnemonic_col,
120	            format!(
121	                "displacement {disp_value} out of range for short form (-128..=127); use `L` to force long form"
122	            ),
123	        ));
124	    }
125	    Ok(Instruction::Short {
126	        op,
127	        tag: insn.tag,
128	        disp: disp_value as i8,
129	    })
130	}
131	
132	fn build_long(
133	    insn: &crate::parser::Instruction,
134	    op: Opcode,
135	    symbols: &SymbolTable,
136	    line: u32,
137	) -> Result<Instruction, AsmError> {
138	    let address = match &insn.operand {
139	        Some(o) => resolve(o, symbols, line)?,
140	        None => 0,
141	    };
142	    if !(-32768..=65535).contains(&address) {
143	        return Err(AsmError::new(
144	            line,
145	            insn.mnemonic_col,
146	            format!("address {address} out of range for long form (16-bit)"),
147	        ));
148	    }
149	    Ok(Instruction::Long {
150	        op,
151	        tag: insn.tag,
152	        indirect: insn.indirect_flag,
153	        address: address as u16,
154	    })
155	}
156	
157	fn resolve(op: &Operand, symbols: &SymbolTable, line: u32) -> Result<i64, AsmError> {
158	    match op {
159	        Operand::Number(n) => Ok(*n),
160	        Operand::Symbol(name) => symbols
161	            .lookup(name)
162	            .ok_or_else(|| AsmError::new(line, 1, format!("undefined symbol `{name}`"))),
163	    }
164	}
165	
166	/// Map a lowercased mnemonic to its `Opcode`. Anything not in the
167	/// 24-mnemonic set produces a structured error.
168	fn mnemonic_to_opcode(mnem: &str, line: u32, col: u32) -> Result<Opcode, AsmError> {
169	    Ok(match mnem {
170	        "ld" => Opcode::Load,
171	        "ldd" => Opcode::LoadDouble,
172	        "sto" => Opcode::Store,
173	        "std" => Opcode::StoreDouble,
174	        "ldx" => Opcode::LoadIndex,
175	        "stx" => Opcode::StoreIndex,
176	        "lds" => Opcode::LoadStatus,
177	        "sts" => Opcode::StoreStatus,
178	        "a" => Opcode::Add,
179	        "ad" => Opcode::AddDouble,
180	        "s" => Opcode::Subtract,
181	        "sd" => Opcode::SubtractDouble,
182	        "m" => Opcode::Multiply,
183	        "d" => Opcode::Divide,
184	        "and" => Opcode::And,
185	        "or" => Opcode::Or,
186	        "eor" => Opcode::ExclusiveOr,
187	        "sla" => Opcode::ShiftLeft,
188	        "sra" => Opcode::ShiftRight,
189	        "bsc" => Opcode::BranchSkipCondition,
190	        "bsi" => Opcode::BranchStore,
191	        "mdx" => Opcode::ModifyIndex,
192	        "wait" => Opcode::Wait,
193	        "xio" => Opcode::ExecuteInputOutput,
194	        _ => {
195	            return Err(AsmError::new(
196	                line,
197	                col,
198	                format!("unknown mnemonic `{mnem}`"),
199	            ));
200	        }
201	    })
202	}
203	
204	/// Mnemonics that have only the long form (per `docs/spec-examples/
205	/// ibm1130.toml` formats lists).
206	pub fn is_long_only(mnem: &str) -> bool {
207	    matches!(mnem, "xio")
208	}
209	
210	/// Mnemonics that have only the short form.
211	pub fn is_short_only(mnem: &str) -> bool {
212	    matches!(mnem, "wait" | "sla" | "sra")
213	}

12	/// Disassemble a byte stream into asm text. Each instruction
13	/// becomes one line. Errors mid-stream are reported with a virtual
14	/// "line" matching the instruction index (1-based).
15	pub fn disassemble(bytes: &[u8]) -> Result<String, AsmError> {
16	    let mut out = String::new();
17	    let mut offset = 0;
18	    let mut idx: u32 = 1;
19	    while offset < bytes.len() {
20	        let (insn, n) = decode::decode(&bytes[offset..])
21	            .map_err(|e| AsmError::new(idx, 1, format!("decode failed at byte {offset}: {e:?}")))?;
22	        out.push_str(&render_instruction(&insn));
23	        out.push('\n');
24	        offset += n;
25	        idx += 1;
26	    }
27	    Ok(out)
28	}
