fn exec_bsc<S: FormShape>(
    state: &mut CpuState,
    mem: &Memory,
    tag: u8,
    indirect: bool,
    address: u16,
    shape: S,
) -> Result<(), ExecError> {
    let mask = if shape.is_long() {
        // Long form: condition mask is the low 6 bits of the address
        // word per the FC manual. (This conflicts with the codegen's
        // current shape, which uses `address` as a target -- step 11
        // pins this semantics; a future codegen revision will
        // separate the address-from-mask concerns.)
        (address & 0x3F) as u8
    } else {
        shape.short_disp() as u8
    };
    let matched = condition_matches(state, mask);
    if shape.is_long() {
        if !matched {
            // Branch to the address (after applying tag offset and
            // optional indirection).
            let target = destination_address(state, mem, tag, address, indirect);
            state.iar = target;
        }
        // matched => fall through (do not branch).
    } else if matched {
        // Short form: skip next instruction (1 or 2 words).
        if let Ok((_, size)) = mem.decode_at(state.iar) {
            state.iar = state.iar.wrapping_add(size);
        }
    }
    Ok(())
}

fn exec_mdx<S: FormShape>(
    state: &mut CpuState,
    mem: &mut Memory,
    tag: u8,
    indirect: bool,
    address: u16,
    shape: S,
) -> Result<(), ExecError> {
    // Modify index register and skip on result == 0.
    //
    // - Short form: add disp to XR[tag] (or to a memory cell if tag
    //   is 0; the historical 1130 has a "modify cell" mode but we
    //   skip that here).
    // - Long form: set XR[tag] to address.
    //
    // After modification, if the resulting value is zero, skip the
    // next instruction.
    let new_value = if shape.is_long() {
        let v = if indirect {
            mem.read_word(address)
        } else {
            address
        };
        if tag != 0 {
            state.write_xr(tag, v);
        }
        v
    } else {
        let prev = state.read_xr(tag);
        let v = prev.wrapping_add(shape.short_disp() as i16 as u16);
        if tag != 0 {
            state.write_xr(tag, v);
        }
        v
    };
    if new_value == 0 {
        if let Ok((_, size)) = mem.decode_at(state.iar) {
            state.iar = state.iar.wrapping_add(size);
        }
    }
    Ok(())
}

fn condition_matches(state: &CpuState, mask: u8) -> bool {
    if mask == 0 {
        return false;
    }
    let acc = state.acc as i16;
    if mask & 0x01 != 0 && acc == 0 {
        return true;
    }
    if mask & 0x02 != 0 && acc < 0 {
        return true;
    }
    if mask & 0x04 != 0 && acc > 0 {
        return true;
    }
    if mask & 0x08 != 0 && (acc & 1) == 0 {
        return true;
    }
    if mask & 0x10 != 0 && state.carry {
        return true;
    }
    if mask & 0x20 != 0 && state.overflow {
        return true;
    }
    false
}

