fn destination_address(
    state: &CpuState,
    mem: &Memory,
    tag: u8,
    address: u16,
    indirect: bool,
) -> u16 {
    let ea = effective_address(state, tag, address);
    if indirect {
        mem.read_word(ea)
    } else {
        ea
    }
}

