#[test]
fn bsc_long_with_z_mask_skips_branch_when_acc_zero() {
    let mut mem = Memory::new(64);
    // Address word (low 6 bits = mask) = 0x0001 (Z bit). The high
    // bits encode the would-be branch target; we set them to 0 so
    // mask is just 0x01.
    write_insn(
        &mut mem,
        0,
        Instruction::Long {
            op: Opcode::BranchSkipCondition,
            tag: 0,
            indirect: false,
            address: 0x0001,
        },
    );
    let mut state = CpuState::new();
    state.acc = 0; // Z matches
    step(&mut state, &mut mem).unwrap();
    // Z matches -> fall through; IAR stays at 2 (past the BSC long).
    assert_eq!(state.iar, 2);
}

