1	//! Instruction execution: one `step()` per instruction.
2	//!
3	//! BSC condition mask semantics (chosen for this emulator; pinned
4	//! here authoritatively per saga step 11):
5	//!
6	//! ```text
7	//! mask bit | meaning when set
8	//! ---------+-----------------------------------------------------
9	//! 0x01     | Z   -- ACC == 0
10	//! 0x02     | -   -- ACC < 0 (two's-complement)
11	//! 0x04     | +   -- ACC > 0
12	//! 0x08     | E   -- ACC even (low bit clear)
13	//! 0x10     | C   -- carry indicator set
14	//! 0x20     | O   -- overflow indicator set
15	//! ```
16	//!
17	//! **BSC short** (`BSC mask`): tests the displacement byte as the
18	//! mask. If any masked condition matches, **skip** the next
19	//! instruction (advance IAR by that instruction's word size).
20	//! Mask = 0 means no condition tested -> never skip.
21	//!
22	//! **BSC long** (`BSC L target [, mask]`): always-unconditional
23	//! branch to `target` in this emulator. The historical 1130 also
24	//! supported a mask in the long form's reserved bits, but the ISA
25	//! spec at saga step 7 marked those bits as reserved-zero; the
26	//! `mask` operand the asm accepts is parsed but currently dropped
27	//! (acknowledged limitation, postmortem item for step 12).
28	//!
29	//! Conditional branch idiom on this emulator: `BSC mask` (skip on
30	//! condition) followed by `BSC L target, 0` (unconditional jump).
31	//! The combination effects "branch unless condition matched".
32	//!
33	//! ACC sign is tested in **two's-complement** terms (the natural
34	//! interpretation; the historical 1130 used sign-magnitude, which
35	//! diverges only at the value 0x8000 for `+` vs `-`).
36	
37	use sw_isa_core::DecodeError;
38	
39	use crate::memory::Memory;
40	use crate::state::CpuState;
41	use sw_ibm1130_isa::{Instruction, Opcode};
42	
43	/// Errors a step() can produce.
44	#[derive(Debug, Clone, PartialEq, Eq)]
45	pub enum ExecError {
46	    Halted,
47	    Decode(String),
48	    Unsupported(Opcode),
49	    DivideByZero,
50	}
51	
52	impl From<DecodeError> for ExecError {
53	    fn from(e: DecodeError) -> Self {
54	        ExecError::Decode(format!("{e:?}"))
55	    }
56	}
57	
58	/// Decode + execute one instruction. Advances IAR; halts on WAIT.
59	pub fn step(state: &mut CpuState, mem: &mut Memory) -> Result<(), ExecError> {
60	    if state.halted {
61	        return Err(ExecError::Halted);
62	    }
63	    let (insn, size_words) = mem.decode_at(state.iar)?;
64	    state.iar = state.iar.wrapping_add(size_words);
65	    state.instr_count += 1;
66	    match insn {
67	        Instruction::Short { op, tag, disp } => exec_short(state, mem, op, tag, disp),
68	        Instruction::Long {
69	            op,
70	            tag,
71	            indirect,
72	            address,
73	        } => exec_long(state, mem, op, tag, indirect, address),
74	    }
75	}
76	
77	/// Run until the CPU halts (Wait instruction) or `max_steps` is
78	/// reached. Returns the number of instructions executed.
79	pub fn run(state: &mut CpuState, mem: &mut Memory, max_steps: u64) -> Result<u64, ExecError> {
80	    let start = state.instr_count;
81	    while !state.halted && state.instr_count - start < max_steps {
82	        step(state, mem)?;
83	    }
84	    Ok(state.instr_count - start)
85	}
86	
87	fn effective_address(state: &CpuState, tag: u8, base: u16) -> u16 {
88	    base.wrapping_add(state.read_xr(tag))
89	}
90	
91	/// Operand for memory-reference ops: word at the effective address,
92	/// with optional indirection (long form only).
93	fn fetch_operand(state: &CpuState, mem: &Memory, tag: u8, address: u16, indirect: bool) -> u16 {
94	    let ea = effective_address(state, tag, address);
95	    let direct = mem.read_word(ea);
96	    if indirect {
97	        mem.read_word(direct)
98	    } else {
99	        direct
100	    }
101	}
102	
103	/// Address used as a *destination* by store-style ops -- after
104	/// indirection, this is the word we modify.
105	fn destination_address(
106	    state: &CpuState,
107	    mem: &Memory,
108	    tag: u8,
109	    address: u16,
110	    indirect: bool,
111	) -> u16 {
112	    let ea = effective_address(state, tag, address);
113	    if indirect { mem.read_word(ea) } else { ea }
114	}
